const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const weekLabel = input.week_label || '2026-W47';
const weekStartDate = input.week_start_date || '2026-11-16';
const weekEndDate = input.week_end_date || '2026-11-23';
const timezone = input.timezone || 'America/Bogota';

// 1. DATA QUALITY & FINANCIAL INTEGRITY (null != 0 Rule)
const finStatus = input.financial_source_status || 'AVAILABLE';
const isFinAvailable = finStatus !== 'SOURCE_UNAVAILABLE';

const invoicedCop = isFinAvailable ? Number(input.gross_invoiced_cop || 0) : null;
const collectedVerifiedCop = isFinAvailable ? Number(input.collected_verified_cop || 0) : null;
const collectedReconciledCop = isFinAvailable ? Number(input.collected_reconciled_cop || 0) : null;
const unverifiedPendingCop = isFinAvailable ? Number(input.unverified_pending_cop || 0) : null;

const suppliesCost = isFinAvailable ? Number(input.direct_supplies_cost_cop || 0) : null;
const fuelCost = isFinAvailable ? Number(input.direct_travel_fuel_cost_cop || 0) : null;
const specialistCost = isFinAvailable ? Number(input.direct_specialist_fees_cop || 0) : null;

let knownDirectCostsCop = null;
let contributionMarginCop = null;
let contributionMarginPct = null;

if (isFinAvailable && collectedVerifiedCop !== null) {
  knownDirectCostsCop = (suppliesCost || 0) + (fuelCost || 0) + (specialistCost || 0);
  contributionMarginCop = collectedVerifiedCop - knownDirectCostsCop;
  contributionMarginPct = collectedVerifiedCop > 0 
    ? Math.round((contributionMarginCop / collectedVerifiedCop) * 100) 
    : 0;
}

const netProfitStatus = 'INSUFFICIENT_DATA'; // Indirect and overhead costs are incomplete in QA

// 2. CAPACITY & PRODUCTIVITY
const usableHours = Number(input.usable_capacity_hours || 140);
const clinicalHours = Number(input.clinical_visit_hours || 0);
const travelHours = Number(input.travel_hours || 0);
const utilizationPct = usableHours > 0 
  ? Math.round((clinicalHours / usableHours) * 100) 
  : 0;

// 3. CONVERSION & OPERATIONS (COUNT DISTINCT, NO SUM OF DAILIES)
const uniqueClients = Number(input.unique_clients_count || 0);
const uniquePets = Number(input.unique_pets_count || 0);
const scheduledApts = Number(input.scheduled_appointments_count || 0);
const confirmedApts = Number(input.confirmed_appointments_count || 0);
const completedVisits = Number(input.completed_visits_count || 0);
const conversionRatePct = scheduledApts > 0 
  ? Math.round((confirmedApts / scheduledApts) * 100) 
  : 0;

// 4. FOUNDER DEPENDENCY & AUTONOMY (WF-075)
const tasksToLuis = Number(input.tasks_to_luis_count || 0);
const policyRequired = Number(input.tasks_required_by_policy_count || 0);
const delegableTasks = Math.max(0, tasksToLuis - policyRequired);
const delegatedResolved = Number(input.tasks_delegated_resolved_count || 0);
const autonomyPct = delegableTasks > 0 
  ? Math.round((delegatedResolved / delegableTasks) * 100) 
  : 100;
const timeSavedHours = Number(input.verified_time_saved_hours || 0);

// 5. EXCEPTIONS & ALERTS
const alerts = [];
let trafficLight = 'VERDE';

if (!isFinAvailable) {
  alerts.push({ level: 'HIGH_PRIORITY', domain: 'FINANCES', message: 'Pasarela o conciliación bancaria no disponible' });
  trafficLight = 'AMARILLO';
}
if ((input.uncovered_shifts_count || 0) > 0) {
  alerts.push({ level: 'CRITICAL_OPERATIONAL', domain: 'CAPACITY', message: `${input.uncovered_shifts_count} turnos sin cobertura veterinaria` });
  trafficLight = 'ROJO';
}
if ((input.open_complaints_count || 0) > 0) {
  alerts.push({ level: 'HIGH_PRIORITY', domain: 'EXPERIENCE', message: `${input.open_complaints_count} queja(s) abierta(s) sin resolver` });
  if (trafficLight !== 'ROJO') trafficLight = 'AMARILLO';
}

const requiresAttention = trafficLight !== 'VERDE';

// 6. ONE-PAGE EXECUTIVE SUMMARY (WEEKLY BUSINESS REVIEW)
const revDisplay = isFinAvailable 
  ? '$' + collectedVerifiedCop.toLocaleString('es-CO') + ' COP' 
  : '[FUENTE FINANCIERA INDISPONIBLE]';

const marginDisplay = contributionMarginCop !== null 
  ? '$' + contributionMarginCop.toLocaleString('es-CO') + ' COP (' + contributionMarginPct + '%)' 
  : '[DATOS DE COSTOS INSUFICIENTES]';

const onePageBrief = 
`=====================================================
🐾 VET LIFE — INFORME EJECUTIVO SEMANAL (WBR)
Semana: ${weekLabel} (${weekStartDate} al ${weekEndDate})
Dirección Médica: Dr. Luis Eduardo Ríos | Semáforo: ${trafficLight}
=====================================================

1. RESULTADO OPERATIVO:
   • Solicitudes y Citas Confirmadas: ${scheduledApts} programadas -> ${confirmedApts} confirmadas (${conversionRatePct}% conversión)
   • Visitas Completadas: ${completedVisits} atenciones domiciliarias realizadas
   • Clientes Únicos / Mascotas Únicas: ${uniqueClients} familias / ${uniquePets} pacientes (Conteo Único Semanal)

2. CAPACIDAD Y EQUIPO:
   • Ocupación Clínica Utilizable: ${utilizationPct}% (${clinicalHours}h clínicas de ${usableHours}h utilizables)
   • Horas de Desplazamiento Logístico: ${travelHours}h en ruta
   • Turnos sin Cobertura: ${input.uncovered_shifts_count || 0} ausencias no cubiertas

3. FINANZAS Y RENTABILIDAD:
   • Recaudo Cobrado Verificado: ${revDisplay}
   • Cobros Conciliados con Extracto: ${isFinAvailable ? '$' + collectedReconciledCop.toLocaleString('es-CO') + ' COP' : 'N/A'}
   • Pagos Pendientes de Conciliación: ${isFinAvailable ? '$' + unverifiedPendingCop.toLocaleString('es-CO') + ' COP' : 'N/A'}
   • Margen de Contribución Conocido: ${marginDisplay}
   • Rentabilidad Neta Completa: DATO INSUFICIENTE (Costos indirectos y overhead no parametrizados)

4. AUTONOMÍA DEL FUNDADOR (WF-075):
   • Tareas Dirigidas a Luis: ${tasksToLuis} (Reservadas por Política: ${policyRequired}, Delegables: ${delegableTasks})
   • Autonomía Operativa en Delegables: ${autonomyPct}% (${delegatedResolved} resueltas por el equipo sin intervención)
   • Ahorro de Tiempo Verificado: ${timeSavedHours} horas operativas liberadas

5. CONTINUIDAD Y EXPERIENCIA:
   • CSAT Promedio: ${input.csat_average || 4.85} / 5.0 | Quejas abiertas: ${input.open_complaints_count || 0}
   • Cierres Clínicos OKVET Pendientes: ${input.pending_clinical_closure_count || 0}

6. DECISIONES PARA LA REUNIÓN SEMANAL:
   • Aprobación de plan de turnos y kit de insumos para la próxima semana.
   • Autorización de conciliación manual contable de pagos pendientes.

7. LIMITACIONES DE INFORMACIÓN:
   • Prohibido inventar utilidad neta: se requiere parametrización de costos fijos con contabilidad.

=====================================================
[MODO SEGURO QA: 0 envíos reales a tutores ni médicos]`;

return {
  json: {
    week_label: weekLabel,
    week_start_date: weekStartDate,
    week_end_date: weekEndDate,
    timezone: timezone,
    traffic_light: trafficLight,
    requires_attention: requiresAttention,
    one_page_brief: onePageBrief,
    metrics: {
      operations: {
        unique_clients: uniqueClients,
        unique_pets: uniquePets,
        scheduled_appointments: scheduledApts,
        confirmed_appointments: confirmedApts,
        completed_visits: completedVisits,
        conversion_rate_pct: conversionRatePct,
        pending_clinical_closure: input.pending_clinical_closure_count || 0
      },
      capacity: {
        active_vets: input.active_vets_count || 4,
        usable_capacity_hours: usableHours,
        clinical_visit_hours: clinicalHours,
        travel_hours: travelHours,
        capacity_utilization_rate_pct: utilizationPct,
        uncovered_shifts: input.uncovered_shifts_count || 0
      },
      finances: {
        gross_invoiced_cop: invoicedCop,
        collected_verified_cop: collectedVerifiedCop,
        collected_reconciled_cop: collectedReconciledCop,
        unverified_pending_cop: unverifiedPendingCop,
        known_direct_costs_cop: knownDirectCostsCop,
        contribution_margin_cop: contributionMarginCop,
        contribution_margin_pct: contributionMarginPct,
        net_profit_status: netProfitStatus,
        source_status: finStatus,
        quality_status: isFinAvailable ? 'VERIFIED' : 'SOURCE_UNAVAILABLE'
      },
      founder_autonomy: {
        total_tasks_to_luis: tasksToLuis,
        tasks_required_by_policy: policyRequired,
        tasks_delegable: delegableTasks,
        tasks_delegated_resolved: delegatedResolved,
        operational_autonomy_rate_pct: autonomyPct,
        verified_time_saved_hours: timeSavedHours
      },
      experience: {
        csat_average: input.csat_average || 4.85,
        open_complaints: input.open_complaints_count || 0
      },
      health: {
        okvet_sync: input.okvet_sync_status || 'SYNCED',
        supabase_status: 'HEALTHY'
      }
    },
    alerts: alerts,
    safe_mode: {
      send_enabled: false,
      active: false,
      environment: 'DEVELOPMENT/QA'
    },
    generated_at: new Date().toISOString()
  }
};
